def roman_to_int(s):
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for c in reversed(s):
        curr = values[c]
        if curr < prev:
            total -= curr
        else:
            total += curr
        prev = curr
    return total

def flatten(nested):
    result = []
    def _flat(x):
        if isinstance(x, list):
            for i in x:
                _flat(i)
        else:
            result.append(x)
    _flat(nested)
    return result

def rotate_matrix(m):
    if not m:
        return []
    return [list(row) for row in zip(*m[::-1])]

def group_anagrams(words):
    if not words:
        return []
    groups = {}
    for w in words:
        key = tuple(sorted(w))
        groups.setdefault(key, []).append(w)
    result = [sorted(g) for g in groups.values()]
    result.sort(key=lambda g: g[0])
    return result

def longest_common_prefix(strs):
    if not strs:
        return ""
    prefix = strs[0]
    for s in strs[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix

def is_valid_ipv4(s):
    if not isinstance(s, str):
        return False
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        if len(p) == 0:
            return False
        if not p.isdigit():
            return False
        if len(p) > 1 and p[0] == '0':
            return False
        try:
            n = int(p)
        except ValueError:
            return False
        if n < 0 or n > 255:
            return False
    return True

def median(nums):
    """Return the median of a non-empty list of numbers."""
    s = sorted(nums)
    n = len(s)
    mid = n // 2
    if n % 2 == 1:
        return s[mid]
    else:
        return (s[mid - 1] + s[mid]) / 2

def chunk(items, size):
    """Split items into lists of length size. The last list may be shorter."""
    return [items[i:i + size] for i in range(0, len(items), size)]

def is_sorted(nums, reverse=False):
    """True if nums is sorted ascending (or descending if reverse=True).
    Equal neighbours are allowed."""
    for a, b in zip(nums, nums[1:]):
        if reverse:
            if a < b:
                return False
        else:
            if a > b:
                return False
    return True

def fib(n):
    """Return the n-th Fibonacci number, with fib(0) = 0 and fib(1) = 1."""
    if n < 2:
        return n
    a, b = 0, 1
    for _ in range(1, n):
        a, b = b, a + b
    return b

def average(nums):
    """Return the mean of a list of numbers."""
    filtered = [n for n in nums if n is not None]
    if not filtered:
        return None
    return round(sum(filtered) / len(filtered), 2)
